local total = {}
for n, rm in ipairs(Rooms) do
  local c = 0
  for _, row in ipairs(rm.tiles) do for _ in row:gmatch("k") do c = c + 1 end end
  total[n] = c
end

local ASSIST = false -- true only in the assisted variant (see socavon_assist in the notes): a bot-side shortcut, NOT the game
local PARTIAL = {} -- rooms where the search proved the portal unreachable with every key taken
local function assist()
  if not (ASSIST and PARTIAL[GAME.room] and state == "play" and M.dead == 0) then return end
  if ASSIST == "skip" then R.keys = 0 R.open_portal() elseif R.keys ~= 0 then return end
  for ty = 0, 15 do for tx = 0, 27 do
    if R.char(tx, ty) == "X" then M.x, M.y, M.ground, M.vy, M.vx = tx * 8 - 4, ty * 8 - 2, true, 0, 0 return end
  end end
end

local die0 = M.die
M.die = function() -- the cause of each death goes to the log (DEATH lines), for the report
  if M.dead == 0 and state == "play" then
    local cause = "fall"
    local corner = false
    for _, p in ipairs(M.corners()) do if R.is_hazard(R.char(math.floor(p[1]) // 8, math.floor(p[2]) // 8)) then corner = true end end
    if GAME.air <= 0 then cause = "air" elseif G.hits(M.x, M.y) then cause = "guard" elseif corner then cause = "hazard" elseif M.y > R.H * 8 then cause = "pit" end
    if cause == "guard" then for _, gd in ipairs(G.list) do if math.abs(gd.x - M.x) < 10 and math.abs(gd.y - M.y) < 13 then cause = "guard_" .. gd.kind end end end
    log(string.format("DEATH room=%d cause=%s t=%d x=%.0f y=%.0f keys_left=%d", GAME.room, cause, G.list[1] and G.list[1].t or -1, M.x, M.y, R.keys))
  end
  return die0()
end

local best = 0
local function raw_progress()
  if state == "load" or state == "title" or state == "demo" then return 0 end
  if state == "win" then return #Rooms * 100 end
  local room = GAME.room
  if state == "clear" then return room * 100 end
  return (room - 1) * 100 + (total[room] - R.keys)
end

local mi, mroom = 1, 0 -- the imperfect players' next event, per room
local function guard_near(x0, x1, y0, y1)
  for _, gd in ipairs(G.list) do
    if gd.kind ~= "ojo" or (gd.t // 60) % 2 == 1 or (gd.t // 60) % 2 == 0 and (gd.t % 60) > 40 then
      if gd.x > x0 - 10 and gd.x < x1 + 10 and gd.y > y0 - 13 and gd.y < y1 + 13 then return true end
    end
  end
  return false
end

local waited = 0
local function human_intent()
  local out = {}
  if M.dead > 0 or not M.ground then return out end
  local ev = MACROS[GAME.room]
  if mroom ~= GAME.room or (G.list[1] and G.list[1].t <= 1) then mi, mroom = 1, GAME.room end
  -- the event for this floor: the next one in the route if it is on this floor, else the nearest one on this floor
  local cand = ev[mi]
  if not cand or math.abs(cand[2] - M.y) > 1 then
    local bd
    cand = nil
    for i, e in ipairs(ev) do
      if math.abs(e[2] - M.y) <= 1 then
        local d = math.abs(e[1] - M.x) + (i < mi and 40 or 0)
        if not bd or d < bd then bd, cand, mi = d, e, i end
      end
    end
  end
  if not cand then return out end
  local skill = PT_CFG.skill or 0.5
  -- a player jumps a walking guard that comes at him (a reflex: it has the bot's reaction delay on top)
  for _, gd in ipairs(G.list) do
    if gd.k.axis == "x" and gd.wave == 0 and math.abs(gd.y - M.y) <= 8 then
      local dx = M.x - gd.x
      if math.abs(dx) <= 27 and math.abs(dx) >= 10 and (dx > 0) == (gd.dir > 0 and false or gd.dir < 0) then out.a = true return out end
    end
  end
  local lead = math.floor(30 - 25 * skill + 0.5) -- a player who knows the delay of his hands presses that much earlier
  local dx = cand[1] - M.x
  local going = dx > 0 and 1 or -1
  if math.abs(dx) <= 1.5 or (math.abs(dx) <= lead and going == cand[3]) then
    if cand[3] == 1 then out.right = true elseif cand[3] == -1 then out.left = true end
    if cand[4] == 1 then out.a = true end
    mi = mi + 1
  else
    out[going == 1 and "right" or "left"] = true
  end
  return out
end

local function tape_intent()
  local out = {}
  if M.dead > 0 then return out end
  local c = TAPES[GAME.room]:sub((G.list[1] and G.list[1].t or 0) + 1, (G.list[1] and G.list[1].t or 0) + 1)
  if c == "" then return out end
  local v = tonumber(c)
  if v & 1 ~= 0 then out.left = true end
  if v & 2 ~= 0 then out.right = true end
  if v & 4 ~= 0 then out.a = true end
  return out
end

PLAYTEST = {
  playing = function() return state == "play" end,
  progress = function()
    if state == "load" or state == "title" then best = 0 end
    best = math.max(best, raw_progress())
    return best
  end,
  done = function()
    if state == "win" then return "win" end
    if state == "over" then return "lose" end
  end,
  where = function() return "room_" .. GAME.room end,
  deaths = function() return GAME.deaths end,
  probe = function() return {n_lives = GAME.lives, n_score = GAME.score, n_keys = R.keys, mx = M.x, my = M.y} end,
  stuck_ticks = 6000, -- more than the air lasts (4500): a player who waits for it to run out is not stuck
  perfect = function()
    assist()
    if PT_CFG.mode == "perfect" then return tape_intent() end
    return human_intent()
  end,
}
